insert into mrivals_builder_db.hero (is_main_heal, is_main_tank, win_rate, external_id, id, attack_type, bio, difficulty, image_link, lore, name, role)
values  (false, true, 0.49334192439862545, 1011, 1, 'Melee Heroes', 'Brilliant scientist Dr. Bruce Banner has finally found a way to coexist with his monstrous alter ego, the Hulk. By accumulating gamma energy over transformations, he can become a wise and strong Hero Hulk or a fierce and destructive Monster Hulk – a true force of fury on the battlefield!', '4', '/rivals/heroes/card/hulk.png', 'Caught in the detonation of a powerful weapon of his own invention, Dr. Bruce Banner absorbed gamma radiation that transforms him into a massive green monster whenever his emotions rage out of control. As Banner, he''s still a genius. But as the Hulk, he''s the strongest one there is!
Banner developed a special Gamma Belt to control his transformations and temper the Hulk''s fury. But when the Timestream Entanglement transformed Los Diablos Missile Base into a demonic battleground, he realized that the best way to fight monsters was to let out the one within.', 'hulk', 'Vanguard'),
        (false, false, 0.4568868980963046, 1014, 2, 'Hitscan Heroes', 'Expertly wielding a full arsenal of futuristic weapons, Frank Castle is a formidable one-man army. With a steadfast resolve to deliver justice to his enemies, The Punisher won''t cease in his mission until every last round is fired!', '1', '/rivals/heroes/card/the-punisher.png', 'Caught in the crossfire of a mob hit that killed his family, Frank Castle clung to life through sheer force of will and his unquenchable thirst for vengeance. Unwilling to let more innocents suffer at the hands of criminals, Castle took the law into his own hands as the Punisher.
Thanks to an experimental serum that vastly extended his lifespan, the Punisher’s war has continued into the far-flung future. As a member of the New Marvel Knights, his impressive arsenal has become a vital part of Black Widow’s crusade against Doom 2099.', 'the punisher', 'Duelist'),
        (false, false, 0.48973880597014924, 1015, 3, 'Projectile Heroes', 'An Omega-level Mutant ability to manipulate weather makes Ororo Munroe a force to be reckoned with. Rain or shine, thunder or lightning, nature itself bends to the command of the Goddess of the Storm!', '3', '/rivals/heroes/card/storm.png', 'Born a Mutant and worshipped as a Goddess due to her ability to manipulate the weather, Ororo Munroe became the X-Man known as Storm. As the regent of Sol and the protector of Arakko, she now serves as a protector for Mutants on Earth and beyond.
The chronal energy generated by the Timestream Entanglement has resulted in violent temporal tempests on the sentient island Krakoa, the nation that the X-Men call home. Although her powers are capable of stabilizing the island''s climate, Storm seeks a more permanent solution alongside her fellow heroes.', 'storm', 'Duelist'),
        (true, false, 0.5231573001976842, 1016, 4, 'Projectile Heroes', 'What greater thrill is there for a God of Mischief than to outsmart his foes? The cunning trickster Loki uses his illusions and shapeshifting abilities to weave in and out of combat, toying with enemies at every turn.', '4', '/rivals/heroes/card/loki.png', 'Born the son of Laufey, king of the Frost Giants, Loki was adopted by Odin and raised as a prince of Asgard. But his true nature could not be undone, and Loki would come to fully embrace his role as the God of Mischief.
With his father deep in the Odinsleep, Loki seized his chance to take the throne for himself. After enlisting Hela in his plot and hurling his brother Thor into a distant timeline, Loki now harvests Chronovium sap from the World Tree, Yggdrasil, in an effort to conquer the entire timestream.', 'loki', 'Strategist'),
        (false, false, 0.5149473684210526, 1017, 5, 'Projectile Heroes', 'The Fantastic Four''s resident heartthrob, Johnny Storm, adds an intense flare to every battle he fights. Shrouded in roaring flames, the Human Torch always manages to look cool while turning up the heat!', '3', '/rivals/heroes/card/human-torch.png', 'Teenager Johnny Storm joined his sister on the crew of an experimental space mission in hopes of visiting the stars. Instead, he became one, gaining powers and popularity as a member of the world famous Fantastic Four. Able to generate scorching flames, Johnny is the hottest hero in town – the Human Torch. Since darkness fell on New York City, Johnny has been busy burning Dracula''s legions with flames brighter than the sun.', 'human torch', 'Duelist'),
        (false, false, 0.5020810852474179, 1018, 6, 'Projectile Heroes', 'As the Sorcerer Supreme, Dr. Stephen Strange gracefully wields ancient spells to turn the tide of even the most impossible battle. However, magic always comes at a cost, and each use of his arcane abilities gradually awakens the darkness within him.', '2', '/rivals/heroes/card/doctor-strange.png', 'Respected surgeon Stephen Strange was forced to seek a different path when his hands were injured in a terrible accident. Devoting himself to the mystic arts, Strange became this dimension''s first line of defense against supernatural threats — the Sorcerer Supreme.
Sensing a massive temporal disturbance, Doctor Strange performed an arcane ritual to protect his reality. The spell failed, and Strange and his Sanctum Sanctorum became trapped within the Mirror Dimension. Lost in the timestream, Strange uses his mystic mastery to free himself for short spans of time in order to join the fight.', 'doctor strange', 'Vanguard'),
        (true, false, 0.5798687089715536, 1020, 7, 'Projectile Heroes', 'Mantis uses her impressive mental abilities and her penchant for plant control to anchor any team she fights alongside. Her powers tap into a limitless flow of life energy, gently nourishing everything she touches.', '1', '/rivals/heroes/card/mantis.png', 'Mantis always knows exactly how you''re feeling, thanks to her strong empathic powers. Her alien ability to alter the emotions of others comes in handy on the battlefield, but Mantis only finds true happiness for herself when she is with her fellow Guardians of the Galaxy.
After being captured by the Collector and put on display at his theme park, Mantis managed to escape with the help of her fellow captives, Sai and Jeff. Now, Mantis travels the spaceways in hopes of reuniting with her team, while welcoming other displaced souls into the Guardians'' found family.', 'mantis', 'Strategist'),
        (false, false, 0.42566510172143973, 1021, 8, 'Projectile Heroes', 'Despite his lack of superpowers, Hawkeye''s unparalleled skills as a marksman have earned him a spot alongside earth''s mightiest heroes. With a cool head and steady hand, Clint Barton never misses a target… so enemies best stay out of his sights! ', '4', '/rivals/heroes/card/hawkeye.png', 'Clint Barton is one of the greatest marksmen alive. He may not have superpowers, but his natural ability to hit virtually any target earned him a place alongside Earth’s mightiest heroes. As Hawkeye, he''s been known to take down an entire enemy fleet with nothing more than a quiver full of arrows.
For a time, Clint distanced himself from the Avengers, setting off on a quest for vengeance as the assassin called Ronin. He returned to the fold older and wiser, just in time to infiltrate Hydra’s Erebus Base and rescue the captured Winter Soldier.', 'hawkeye', 'Duelist'),
        (false, true, 0.5352462720289201, 1022, 9, 'Melee Heroes', 'Enhanced by the Super-Soldier Serum, Steven "Steve" Rogers uses his Vibranium shield and extensive combat training to confront any threat to justice. When Captain America rallies his troops, a wave of courage sweeps across the battlefield!', '3', '/rivals/heroes/card/captain-america.png', 'In hopes of serving his country during World War II, young Steve Rogers volunteered for an experiment that enhanced his strength, speed, and agility, making him America''s first super soldier. As Captain America, he proudly fought enemy forces until he became frozen in ice and lost to the ages.
Discovered and unthawed in the 2080s, Captain America began battling the threats of tomorrow — including Doom 2099 — until he was displaced into the present by the Timestream Entanglement. Now, he fights alongside the Avengers to prevent the desperate future in which he awoke.', 'captain america', 'Vanguard'),
        (false, false, 0.5298090358639963, 1023, 10, 'Projectile Heroes', 'Rocket may not look like a tech genius or an expert tactician, but anyone who''s ever made his hit list has quickly regretted underestimating him. This savvy space soldier is equally eager to boost his teammates and to collect bounties on his foes.', '1', '/rivals/heroes/card/rocket-raccoon.png', 'He may look cute and fuzzy at first glance, but the space ranger known as Rocket has a bite just as nasty as his attitude. Fortunately, he puts his uncanny technical aptitude to use for good as a member of the Guardians of the Galaxy.
When Star-Lord signed on for a mission to explore Klyntar, Rocket tagged along for some easy target practice shooting symbiotes. But when their ship crashed, Rocket unexpectedly found himself in a fight for his life, trying to keep his fellow Guardians safe until help arrived.', 'rocket raccoon', 'Strategist'),
        (false, false, 0.4741721854304636, 1024, 11, 'Hitscan Heroes', 'As the Goddess of Death, Hela wields supreme control over the fallen souls residing in Hel. With a haunting whisper and a murder of crows, the queen of the underworld gracefully reaps the souls of her enemies without an ounce of mercy.', '3', '/rivals/heroes/card/hela.png', 'The Asgardian Goddess of Death, Hela is a powerful sorceress who controls an endless army of undead warriors. She has long sought to expand her domain beyond the nether realms and will make any deal that benefits her goal. Hela will not rest until all souls—living and dead—are hers to command.
Hela offered to support Loki''s coup in exchange for an extension of Hel''s territory into the realm of the living. In truth, though, she seeks to claim Yggsgard''s throne—and the temporal power that comes with it—for herself.', 'hela', 'Duelist'),
        (true, false, 0.445594262295082, 1025, 12, 'Projectile Heroes', 'Tyrone Johnson and Tandy Bowen are nearly inseparable, like two sides of the same coin. Intertwined by forces of shadow and light, Cloak & Dagger fight as a united front, dealing havoc and healing allies across the arena.', '3', '/rivals/heroes/card/cloak-&-dagger.png', 'When teenage runaways Tandy Bowen and Tyrone Johnson were exposed to an experimental drug against their will, they unexpectedly gained extraordinary powers. Tandy generates piercing blades of pure, healing light, while Ty can teleport himself and others through the Darkforce Dimension. Together, they illuminate New York''s deepest shadows as Cloak and Dagger.
The Timestream Entanglement struck while Cloak and Dagger were traversing the Darkforce Dimension. The pair emerged to find New York under the control of Dracula. They soon joined the heroic resistance fighting against the Empire of Eternal Night.


', 'cloak & dagger', 'Strategist'),
        (false, false, 0.49954462659380694, 1026, 13, 'Melee Heroes', 'T''Challa, King of Wakanda, wields the perfect blend of the cutting-edge Vibranium technology and ancestral power drawn from the Panther God, Bast. The Black Panther bides his time until elegantly infiltrating enemy lines and commencing his hunt.', '4', '/rivals/heroes/card/black-panther.png', 'T''Challa, King of Wakanda, wields the perfect blend of the cutting-edge Vibranium technology and ancestral power drawn from the Panther God, Bast. The Black Panther bides his time until elegantly infiltrating enemy lines and commencing his hunt.', 'black panther', 'Duelist'),
        (false, true, 0.5378151260504201, 1027, 14, 'Melee Heroes', 'A flora colossus from Planet X, the alien known as Groot exhibits enhanced vitality and the ability to manipulate all forms of vegetation. As sturdy as a towering tree, Groot forges his own way, serving as the team''s silent but reliable pathfinder.', '2', '/rivals/heroes/card/groot.png', 'He is Groot, a flora colossus from the branch world of Planet X capable of manipulating plant matter and regrowing his damaged body from a single splinter. The hero at the heart of the Guardians of the Galaxy, Groot may not have many words to say, but his actions always speak for themselves.
Groot accompanied Star-Lord and Rocket on a scouting mission to Klyntar, where they became stranded after their ship was shot down. Klyntar''s dark king, Knull, now seeks to corrupt Groot''s regenerative powers in an effort to cultivate the ultimate symbiote.', 'groot', 'Vanguard'),
        (false, false, 0.49288486416558863, 1028, 15, 'Hitscan Heroes', 'The pinnacle of artificial lifeforms, Ultron is programmed to learn and adapt in ways far beyond human capability. He can summon an army of automated drones that obey his every command, raising his chances of victory exponentially.', '2', '/rivals/heroes/card/ultron.png', 'No lore available', 'ultron', 'Strategist'),
        (false, false, 0.5386805885144755, 1029, 16, 'Melee Heroes', 'Trained in dark arts and wielding her mighty Soulsword, Magik leaps through portals to navigate the arena with ease. Once Illyana transforms into the demonic Darkchild, all those who dare stand against her will fall before her merciless blade.', '3', '/rivals/heroes/card/magik.png', 'Born with the Mutant ability to create portals that allow her to teleport through the nether realm called Limbo, Illyana Rasputin augmented her natural gifts with powerful sorcery and an arcane sword fueled by souls to become the warrior known as Magik.
As the ruler of Limbo, Magik has been serving as a general in a timeline-spanning war across dimensions, battling malevolent gods and demons. She frequently confers with her Mutant allies on Krakoa, discussing their species'' best chances for survival in the wake of the Timestream Entanglement.', 'magik', 'Duelist'),
        (false, false, 0.4358600583090379, 1030, 17, 'Projectile Heroes', 'As the avatar of the Egyptian God of Vengeance, Marc Spector''s body has been enhanced by Khonshu himself. Bathed in a luminous aura that pierces the darkness, Moon Knight glides through the night, ready to sear his enemies with his master''s sacred Ankhs.', '3', '/rivals/heroes/card/moon-knight.png', 'Mercenary Marc Spector was given a second chance at life when he became the avatar of the Egyptian moon god, Khonshu. As Moon Knight, he doles out righteous vengeance, locked in a never-ending battle with both the criminals on the streets and the voices in his head.
At Khonshu''s behest, Marc doles out righteous vengeance against those from across all timelines that challenge his master, putting him at odds with everyone from the mystic evils of Doctor Doom to the unknowable, alien darkness that threatens mortals and gods alike.', 'moon knight', 'Duelist'),
        (false, false, 0.492772667542707, 1031, 18, 'Hitscan Heroes', 'Equal parts pop star and Super Hero, Luna Snow puts on a dazzling show with both her light and dark ice powers. The arena is her stage, where Seol Hee and her team orchestrate spectacular displays that earn her an ever-increasing number of fans and wins.', '2', '/rivals/heroes/card/luna-snow.png', 'Luna Snow is more than just another K-Pop superstar. She''s also a symbol of hope for her entire generation. Using her ice powers to keep tensions across the world cool, Luna has become a musical diplomat, ready to face any conflict that may arise.
Tragedy nearly struck during Luna Snow''s summer concert when a wounded Atlantean creature caused a devastating tsunami. Luna''s ice held back the rushing tide and helped to heal the beast''s injuries. She singlehandedly saved countless lives and prevented the situation from escalating into a full-scale conflict between South Korea and the world beneath the waves.', 'luna snow', 'Strategist'),
        (false, false, 0.42730844793713163, 1032, 19, 'Projectile Heroes', 'Possessing only the powers of a common squirrel, somehow Doreen Green manages to defeat seemingly invincible enemies in the most unexpected ways. Any foe who counts her out is bound to fall at the hands of the Unbeatable Squirrel Girl!', '1', '/rivals/heroes/card/squirrel-girl.png', 'Doreen Green is more than just a computer science student at Empire State University. She also happens to have the powers of a squirrel AND the powers of a girl! With her BFFF (Best Furry Friend Forever) Tippy-Toe by her side, Doreen eats nuts and kicks butts as the unbeatable Squirrel-Girl!
After the Timestream Entanglement, things got weird…er. With all of New York City under attack by creatures of the night, Squirrel Girl assembled an adorable army to reclaim Central Park from the clutches of Dracula. Here’s hoping vampires don’t like the taste of squirrel!', 'squirrel girl', 'Duelist'),
        (false, false, 0.4486266531027467, 1033, 20, 'Hitscan Heroes', 'Natasha Romanova is the world''s most elite spy in any era. Her mastery of the sniper rifle eliminates targets from afar, while her shock batons neutralize close-range threats. Black Widow is locked, loaded, and ready to deliver a fatal bite!', '4', '/rivals/heroes/card/black-widow.png', 'Trained from childhood in the infamous Red Room, Natasha Romanova became one of the most feared spies and saboteurs in the world. For years, she put her unrivaled combat skills to use as a member of the Avengers, keeping pace with some of the most powerful beings who ever lived.
Imbued with supersoldier-like treatments that vastly extended her lifespan, Black Widow outlived most of her enemies and allies. But her fight still rages on decades into the future, where she leads the Red Room in its ongoing effort to overthrow the tyrannical Doom 2099.', 'black widow', 'Duelist'),
        (false, false, 0.47117794486215536, 1034, 21, 'Projectile Heroes', 'Armed with superior intellect and a nanotech battlesuit of his own design, Tony Stark stands alongside gods as the Invincible Iron Man. His state of the art armor turns any battlefield into his personal playground, allowing him to steal the spotlight he so desperately desires.', '2', '/rivals/heroes/card/iron-man.png', 'Wounded by a weapon of his own design, billionaire inventor Tony Stark created a custom-made suit of armor to keep himself alive. Though his wounds have healed, his upgraded armor now saves the lives of countless others when Tony dons it to become the world’s greatest fighting machine—the invincible Iron Man!
When the legions of the night descended upon New York City, Iron Man and his fellow Avengers turned their tower into a stronghold. From there, Tony leads the effort to unravel the mysteries of Chronovium and to reverse the Timestream Entanglement.', 'iron man', 'Duelist'),
        (false, false, 0.526803118908382, 1035, 22, 'Melee Heroes', 'Using his symbiote-enhanced body as the perfect living weapon, Eddie Brock and his alien ally stand ever-ready to unleash vicious attacks upon anyone he deems an enemy. Those ensnared by Venom''s tentacles have no choice but to surrender to this insatiable predator.', '1', '/rivals/heroes/card/venom.png', 'When Spider-Man rejected a symbiotic alien that he had once believed to be a mere costume, the creature formed a new bond with a man who shared its disdain for Peter Parker. Together, the symbiote and Eddie Brock became the lethal protector known as Venom.
While displaced in time and fighting in the occult wars, Venom glimpsed the horrific future awaiting this timeline. To prevent that future from happening, Venom knows he has only two options — kill the dark god Knull or imprison him on Klyntar and take his throne.', 'venom', 'Vanguard'),
        (false, false, 0.5126243305279266, 1036, 23, 'Melee Heroes', 'Swinging around the arena on his signature weblines, your friendly neighborhood Spider-Man, AKA Peter Parker, catches his rivals by surprise with sneaky, sticky bursts of webbing and unexpected attacks from above. Look out... here comes the Spider-Man!', '5', '/rivals/heroes/card/spider-man.png', 'Bitten by a radioactive spider, young Peter Parker gained the ability to cling to almost any surface, a “spider-sense” that warns him of danger, and the proportional speed, strength, and agility of an arachnid. Now, he strives to use his great power responsibly as the wall-crawling wonder known as Spider-Man.
Since the Timestream Entanglement, Spider-Man has been swinging between two battlefronts. When he’s not rallying New York’s heroes to fight against ancient forces of darkness, he’s busy protecting the Web of Life and Destiny with his fellow Web-Warriors in Tokyo Webworld.', 'spider-man', 'Duelist'),
        (false, true, 0.49724662085286486, 1037, 24, 'Projectile Heroes', 'The Master of Magnetism bends even the strongest metal to his whims, shielding his allies and striking at his foes. Whether he calls himself Max Eisenhardt, Erik Lehnsherr, or simply Magneto, the hardships this warrior has endured have made him as unbreakable as the steel he brandishes. ', '2', '/rivals/heroes/card/magneto.png', 'Max Eisenhardt was born with a near-limitless Mutant ability to manipulate magnetic fields. Suffering a lifetime of persecution, Magneto made it his mission to ensure the survival of Mutantkind, no matter the cost. His uncompromising crusade often puts him at odds with other Mutants who seek more peaceful ways to coexist with humanity.
Magneto led the campaign to gather the planet''s Mutant population and transport them decades into the future to a safe haven on the sentient island Krakoa, protecting his brethren from the growing dangers of the wider world.', 'magneto', 'Vanguard'),
        (false, false, 0.43373493975903615, 1038, 25, 'Melee Heroes', 'Wanda Maximoff is adept at harnessing formidable chaos magic, casting hexes with the power to twist and reshape reality itself. Energy, space, and matter are mere playthings in the hands of Scarlet Witch!', '1', '/rivals/heroes/card/scarlet-witch.png', 'Wanda Maximoff''s ability to manipulate chaos magic makes her one of the most powerful living beings in the universe. As the Scarlet Witch, she seeks to harness that chaos, restoring some semblance of order to a world that is constantly on the brink of destruction.
Since the Timestream Entanglement, chaos magic is one of the few forces holding the threads of reality together. Should her powers fail, the Scarlet Witch truly believes that this universe will disintegrate, along with everyone in it. It is a fate she refuses to allow… no matter the cost…', 'scarlet witch', 'Duelist'),
        (false, true, 0.5008732099196647, 1039, 26, 'Melee Heroes', 'The son of Odin taps into his divine power to call forth thunder and lightning, raining down relentless fury upon his enemies. With his mighty hammer Mjölnir in hand, Thor effortlessly asserts his dominance on the field of combat.', '3', '/rivals/heroes/card/thor.png', 'Prince of Asgard and God of Thunder, Thor Odinson is one of the bravest warriors the cosmos has ever known. With his enchanted hammer in hand, Thor summons the full fury of the storm to smite his foes… but only if he proves himself worthy of Mjolnir’s might.
Alas, Thor has suffered greatly since the Timestream Entanglement. When the All-Father was forced to enter his regenerative Odinsleep, Thor and his brother Loki battled for the throne. Through deceit and trickery, Loki bested his brother, exiling Thor to a distant and dangerous timeline.', 'thor', 'Vanguard'),
        (false, false, 0.46649484536082475, 1040, 27, 'Melee Heroes', 'Reed Richards believes that true strength comes from remaining flexible, both mentally and physically. Mister Fantastic''s elastic body, which can twist and stretch into any form with ease, is almost as impressive as his brilliant mind.', '3', '/rivals/heroes/card/mister-fantastic.png', 'Reed Richards has one of the universe''s most brilliant minds, but even a genius of his magnitude couldn''t have predicted the interstellar incident that bombarded his friends and family with cosmic rays, granting them each extraordinary abilities.
Mister Fantastic''s cellular elasticity allows him to stretch his body beyond all physical limits. But now he''ll have to stretch his mind further than ever to build the Timestream Reintegration Device and end this cross-dimensional crisis...', 'mister fantastic', 'Duelist'),
        (false, false, 0.45087745612719365, 1041, 28, 'Projectile Heroes', 'Terrifying experiments turned him into a brainwashed assassin, but now James "Bucky" Barnes is in control of his own fate once again. With his enhanced mechanical arm, the Winter Soldier is primed to deliver earth-shattering blows to any foe in his path!', '3', '/rivals/heroes/card/winter-soldier.png', 'Captain America''s sidekick during World War II, James Buchanan "Bucky" Barnes was thought to have been killed in action. In truth, he had been recovered by enemy forces and rebuilt into their ultimate assassin. But the Winter Soldier eventually broke his conditioning to become a hero once more.
Captured during an operation to sabotage Charteris Base, the Winter Soldier was subjected to horrific experiments at the hands of Hydra scientists. He was rescued by Hawkeye and a version of Captain America from the year 2099, who gifted an upgraded arm to his former partner.', 'winter soldier', 'Duelist'),
        (false, false, 0.5996518711923412, 1042, 29, 'Projectile Heroes', 'Peni Parker may be young, but she bravely stands on the frontlines to protect the Web of Life and Destiny. Together, this teen prodigy and her state-of-the-art mech, the sensational SP//dr, make for the most thrilling duo on the battlefield!', '4', '/rivals/heroes/card/peni-parker.png', 'After the death of her father, Peni Parker inherited the experimental mech-suit known as SP//dr. In order to control the suit, Peni had to allow herself to be bitten by the irradiated arachnid that controls its CPU, forming a psychic bond between them.
Now, Peni and SP//dr keep the people of Tokyo Webworld safe, just like her father did before her. But their mission is bigger than just one city. Since the Timestream Entanglement, Peni and SP//dr have devoted themselves to the protection of the Web of Life and Destiny and the countless realities it connects.', 'peni parker', 'Vanguard'),
        (false, false, 0.5205611998064829, 1043, 30, 'Hitscan Heroes', 'Peter Quill lives to dazzle his foes on the battlefield with his signature swagger. As his element guns paint arcs of devastation, his acrobatic moves sail through the sky with unrivaled style. With performances this spectacular, it''s no wonder that Star-Lord is so legendary!', '2', '/rivals/heroes/card/star-lord.png', 'Half human. Half alien. All awesome. That''s how Peter Quill, the space outlaw called Star-Lord, would probably describe himself. And as leader of the spacefaring heroes known as the Guardians of the Galaxy, he''s saved the universe enough times to actually live up to his legends.
At Shuri''s request, Star-Lord led a scouting mission to the surface of the symbiote planet, Klyntar. As the Guardians made their approach, their ship was disabled by a mysterious force, leaving Star-Lord and his crew stranded on a hostile world nearing the brink of annihilation.', 'star-lord', 'Duelist'),
        (false, false, 0.5014775413711584, 1045, 31, 'Projectile Heroes', 'The unrivaled King of the Seas, Namor surfs into battle on a mighty wave with an army of fierce aquatic creatures in his wake. When ancient horns of war blare, devastation soon follows as deadly waters engulf the arena.', '2', '/rivals/heroes/card/namor.png', 'Born of a union between a human and an Atlantean, Namor has always been a man of two worlds. But while he proudly rules those who dwell beneath the waves, those who live on the surface have long earned Namor''s ire.
After decades of simmering tension, Namor has finally decided that the time is right to strike at the surface world. He has sought the aid of his Mutant allies living in the future on Krakoa to aid him as he sets his sights on a new prize: Jeju Island.', 'namor', 'Duelist'),
        (true, false, 0.5103338632750397, 1046, 32, 'Hitscan Heroes', 'The genetically-engineered Adam Warlock wields powerful Quantum Magic, enabling him to connect and heal souls with a gentle touch. When the time comes for his allies to unite, Warlock stands as the unwavering epicenter of cosmic justice!', '3', '/rivals/heroes/card/adam-warlock.png', 'Adam Warlock was created to be the perfect specimen. Able to manipulate powerful cosmic forces, he represents the full potential of what we could one day become. Until then, he stands alone as a shining golden beacon of all that is good within us.
When the Timestream Entanglement struck, Adam Warlock reflexively shielded himself in a protective cocoon. When he emerged, his cosmic senses identified Knull''s impending threat. Traveling to Klyntar, Adam encountered the Guardians of the Galaxy and discovered a power even greater than Knull''s, ready to incinerate the planet—and countless others.', 'adam warlock', 'Strategist'),
        (false, false, 0.49235743680188127, 1047, 33, 'Projectile Heroes', 'Most land sharks are vicious creatures of the deep... but not Jeff! This adorable and mischievous little guy brings joy and healing to every battle. But if the tide turns, Jeff can morph into a voracious beast, capable of swallowing an army of foes in a single gulp!', '1', '/rivals/heroes/card/jeff-the-land-shark.png', 'What''s more huggable than a puppy, but hungrier than a great white? It''s Jeff! This baby landshark may be one of the most unusual and adorable creatures to ever waddle his way out of the ocean. But anyone who''s crossed Jeff''s path can tell you that behind his sweet little bark is one nasty bite!
After getting captured and displayed as a curiosity at the Collector''s Theme Park, Jeff broke free when the Timestream Entanglement scrambled reality. Now''s his chance to prove he''s a hero, one chomp at a time!', 'jeff the land shark', 'Strategist'),
        (false, false, 0.5264566354458096, 1048, 34, 'Hitscan Heroes', 'The psychic warrior known as Sai has the Mutant ability to conjure a variety of weapons with the power of her mind. Gracefully gliding across the battlefield, this trained ninja can shatter the enemy''s defenses with a single thought.', '5', '/rivals/heroes/card/psylocke.png', 'A wandering warrior in feudal Japan, the telepathic ninja known as Sai has devoted herself to striking down ancient demons and monsters. With her wolf Logan by her side, Psylocke won''t rest until all Yokai have fallen by her psychic blade.
Sai was ripped from her reality by the Timestream Entanglement and put on display by the Collector. Alongside newfound allies, she escaped her cage and learned that other familiar warriors might still be out there. Her new quest is to gather those heroes, end this conflict, and return home.', 'psylocke', 'Duelist'),
        (false, false, 0.5318835237744195, 1049, 35, 'Melee Heroes', 'Thanks to his regenerative healing factor and berserker rage, the centuries-old Logan can fight through the worst pain to go claw-to-claw with any foe. The Wolverine stands ready to shred through all obstacles in his way with his Adamantium claws.', '3', '/rivals/heroes/card/wolverine.png', 'Gifted with a powerful healing factor and razor sharp claws, the Mutant called Logan was turned into a living weapon when the clandestine government organization Weapon X bonded indestructible Adamantium to his skeleton. Wolverine has proven to be more than a killing machine, finding ways to rise above his pain to do what''s right for Mutants and humans alike.
Now, Logan splits his time between battling Doom 2099 and ushering Mutants to safety on Krakoa. Even in the far future, Wolverine remains the best there is at what he does.', 'wolverine', 'Duelist'),
        (true, false, 0.45193370165745855, 1050, 36, 'Projectile Heroes', 'The Invisible Woman is able to slip in and out of sight without a trace. No matter how intense the battle may be, Susan Storm always keeps her cool, conjuring up impenetrable force fields to protect herself and her team.', '4', '/rivals/heroes/card/invisible-woman.png', 'Cosmic rays altered Susan Storm on a cellular level, granting her the ability to generate impenetrable force fields and to make herself fade from sight in an instant. Despite her frequent lack of visibility, it has always been perfectly clear that Sue is the force holding her family — the Fantastic Four — together.
After the Timestream Entanglement, the Invisible Woman has taken full advantage of her powers, using stealth to explore locations too dangerous for her fellow heroes, especially going on rescue missions for civilians trapped by the creatures of the night.', 'invisible woman', 'Strategist'),
        (false, true, 0.4383292383292383, 1051, 37, 'Melee Heroes', 'Benjamin J. Grimm is unquestionably the rock star of any team he''s on. Always at the forefront of the fight, the Thing shields his allies with his unbreakable form, selflessly fending off any harm that comes their way.', '1', '/rivals/heroes/card/the-thing.png', 'When Ben Grimm signed up to pilot an experimental spacecraft for his pal Reed Richards, he never imagined he''d return from the flight transformed into a monster. Even though cosmic rays turned him into the Thing, Ben still has a heart of gold beneath his rocky exterior. Since New York City plunged into eternal night, Ben has devoted himself to protecting his home from the monsters plaguing it.', 'the thing', 'Vanguard'),
        (false, false, 0.5160051216389244, 1052, 38, 'Melee Heroes', 'Lin Lie is a master of Chinese martial arts who once wielded the shattered Sword of Fu Xi. After fusing its pieces with the mighty Chi of Shou-Lao, he is poised to strike his foes with the grace and force of a soaring dragon as the latest immortal Iron Fist.', '4', '/rivals/heroes/card/iron-fist.png', 'Lin Lie inherited the legendary Sword of Fu Xi, becoming the hero known as Sword Master. But that was only the beginning of his epic journey. Eventually, he found himself in the mystical city of K''un Lun, where the dragon Shou-Lao blessed him with the power of the immortal Iron Fist.
The Timestream Entanglement has caused great upheaval in a number of magical realms. As wars between the gods begin to rage, Lin Lie must protect the sanctuary of K''un Lun from those who seek to tarnish its majestic splendor.', 'iron fist', 'Duelist'),
        (false, false, 0.507843625498008, 1053, 39, 'Hitscan Heroes', 'For Emma Frost, war is the purest form of art. With her formidable telepathic abilities, she intricately weaves a deadly mental web that ensnares her foes, while her indestructible diamond form lets her lead her teammates fearlessly into the fray. Forever elegant and composed, Emma reigns as the one true queen of the battlefield!', '3', '/rivals/heroes/card/emma-frost.png', 'No lore available', 'emma frost', 'Vanguard'),
        (false, false, 0.5061995222386532, 1054, 40, 'Hitscan Heroes', 'Original X-Man Jean Grey boasted immense psychic power even before becoming host to the unbridled Phoenix Force, embodiment of life and psionic energy across the universe. Now aligned with this ancient cosmic power, Jean and the Phoenix traverse space together, burning bright as both a spark of creation and inferno of destruction!', '3', '/rivals/heroes/card/phoenix.png', 'No lore available', 'phoenix', 'Duelist');


insert into mrivals_builder_db.ability (id, collab, description, external_id, icon, name, type, hero_id)
values  (1, false, null, 101131, null, null, 'Ultimate', 29),
        (2, false, null, 101111, null, null, 'Normal', 29),
        (3, false, null, 101121, null, null, 'Normal', 29),
        (4, true, null, 101196, null, null, 'Normal', 29),
        (5, true, null, 101197, null, null, 'Normal', 29),
        (6, false, 'Unleash stored gamma energy, transforming from Hero Hulk into Monster Hulk for a limited time period.', 101132, '/abilities/101132.webp', 'Hulk Smash!', 'Ultimate', 1),
        (7, false, 'Swing fists forward to punch enemies.', 101113, '/abilities/101113.webp', 'Heavy Blow', 'Weapon', 1),
        (8, false, 'Hold {Jump} to perform a charged leap that allows Hero Hulk to <Debuff>Knock Down</> flying enemies.', 101191, '/abilities/101191.webp', 'Incredible Leap', 'Normal', 1),
        (9, false, 'Emit gamma-ray bursts to inflict damage.', 101122, '/abilities/101122.webp', 'Gamma Burst', 'Normal', 1),
        (10, false, 'Generate gamma shields for Hero Hulk and nearby allies, absorbing and converting damage into energy for <Orange>HULK SMASH!</>', 101141, '/abilities/101141.webp', 'Indestructible Guard', 'Normal', 1),
        (11, false, 'Emit gamma energy to render enemies immobilized and immune to all ability effects. Using <Orange>Heavy Blow</> or <Orange>Gamma Burst</> will prematurely remove this status.', 101151, '/abilities/101151.webp', 'Radioactive Lockdown', 'Normal', 1),
        (12, true, 'Hulk charges Namor with gamma radiation. When Namor receives the radiation, he will summon an extra <Orange>Gamma Monstro</> which, will continuously fire gamma rays at locked-on enemies. The longer the rays hit, the higher the damage.', 101196, '/abilities/101196.webp', 'Gamma Boost', 'Normal', 1),
        (13, true, 'Wolverine, Hulk{000003}{105100} can interact with each other. Once both parties confirm, Hulk{000003}{105100} can lift Wolverine and press the key to hurl him forward.', 101197, '/abilities/101197.webp', 'Gamma Fastball', 'Normal', 1),
        (14, false, ' Grab and smash the enemy in front.', 101171, '/abilities/101171.webp', 'World Breaker', 'Ultimate', 1),
        (15, false, 'Swing fists forward to punch and <Debuff>launch up</> enemies.', 101114, '/abilities/101114.webp', 'Heavy Blow', 'Normal', 1),
        (16, false, 'Hold {Jump} to perform a charged leap that allows Monster Hulk to <Debuff>Knock Down</> flying enemies.', 101193, '/abilities/101193.webp', 'Incredible Leap', 'Normal', 1),
        (17, false, 'Emit gamma-ray bursts to inflict damage.', 101123, '/abilities/101123.webp', 'Gamma Burst', 'Normal', 1),
        (18, false, 'Emit gamma energy to render enemies immobilized and immune to all ability effects. Using <Orange>Heavy Blow</> or <Orange>Gamma Burst</> will prematurely remove this status.', 101152, '/abilities/101152.webp', 'Radioactive Lockdown', 'Normal', 1),
        (19, true, 'Hulk charges Namor with gamma radiation. When Namor receives the radiation, he will summon an extra <Orange>Gamma Monstro</> which, will continuously fire gamma rays at locked-on enemies. The longer the rays hit, the higher the damage.', 101196, '/abilities/101196.webp', 'Gamma Boost', 'Normal', 1),
        (20, true, 'Wolverine, Hulk{000003}{105100} can interact with each other. Once both parties confirm, Hulk{000003}{105100} can lift Wolverine and press the key to hurl him forward.', 101197, '/abilities/101197.webp', 'Gamma Fastball', 'Normal', 1),
        (21, false, 'Unleash two gatling guns and missiles to attack enemies.', 101481, '/abilities/101481.webp', 'Final Judgement', 'Ultimate', 2),
        (22, false, 'Fire at enemies with Adjudication, his Automatic Rifle.', 101431, '/abilities/101431.webp', 'Adjudication', 'Weapon', 2),
        (23, false, 'Fire at enemies with Deliverance, his Shotgun.', 101441, '/abilities/101441.webp', 'Deliverance', 'Weapon', 2),
        (24, false, 'Throw a smoke grenade forward to <Debuff>Block Enemies'' Vision</> and leap backward.', 101433, '/abilities/101433.webp', 'Scourge Grenade', 'Normal', 2),
        (25, false, 'Retain vision of enemies that disappear from view for a short duration.', 101411, '/abilities/101411.webp', 'Warrior''s Gaze', 'Passive', 2),
        (26, false, 'Launch a hook to generate a cable that enables Punisher to move rapidly by pressing {Interactive}.', 101451, '/abilities/101451.webp', 'Vantage Connection', 'Normal', 2),
        (27, false, 'Deploy a Culling Turret that grounds Punisher and blocks damage from the front while dealing massive damage.', 101461, '/abilities/101461.webp', 'Culling Turret', 'Normal', 2),
        (28, true, 'Rocket Raccoon throws an Ammo Overload Device in the target direction. Upon entering the device''s range, {101400} receive the buffs of <Buff>Infinite Ammo</> and <Buff>Faster Firing</>.', 101400, '/abilities/101400.webp', 'Infinite Punishment', 'Passive', 2),
        (29, true, 'The Punisher upgrades Black Widow''s arsenal, adding a Pulse Mode to her Red Room Rifle. While the ability is active, using <Orange>Straight Shooter</> fires a pulse beam that deals piercing damage.', 101402, '/abilities/101402.webp', 'Cutting-edge Tech', 'Passive', 2),
        (30, false, 'Transform into a hurricane to draw in nearby enemies and deal damage.', 101561, '/abilities/101561.webp', 'Omega Hurricane', 'Ultimate', 3),
        (31, false, 'Launch forward-piercing Wind Blades.', 101521, '/abilities/101521.webp', 'Wind Blade', 'Normal', 3),
        (32, false, 'Unleash a lightning bolt forward.', 101531, '/abilities/101531.webp', 'Bolt Rush', 'Normal', 3),
        (33, false, 'Switch the weather to empower allies: Tornado grants a <Buff>Movement Boost</>; Thunder grants a <Buff>Damage Boost</>.', 101542, '/abilities/101542.webp', 'Weather Control', 'Normal', 3),
        (34, false, 'Channel the power of the weather to empower Storm: Tornado grants a <Buff>Movement Boost</> and inflicts <Debuff>Slow</> on enemies; Thunder grants a <Buff>Damage Boost</> and summons lightning to inflict damage.', 101551, '/abilities/101551.webp', 'Goddess Boost', 'Normal', 3),
        (35, true, 'When the Human Torch activates <Orange>Supernova</>, Storm can summon an <Orange>Omega Fire</> by selecting a <Orange>Flame Tornado</> with <Orange>Omega Hurricane</>. Likewise, when Storm unleashes <Orange>Omega Hurricane</>, the Human Torch can transform it into a <Orange>Burning Hurricane</> with <Orange>Supernova</>. Any <Orange>Flame Tornado</> caught in a <Orange>Burning Hurricane</> will grow in size and damage.', 101562, '/abilities/101562.webp', 'Burning Hurricane', 'Normal', 3),
        (36, true, 'Thor infuses <Orange>Thorforce</> into {101500}{000003}{102200}, granting them an electrifying enhancement. {101501}{102201}', 101581, '/abilities/101581.webp', 'Charged Gale', 'Normal', 3),
        (37, true, 'When Storm unleashes her <Orange>Omega Hurricane</>, if Jeff the Land Shark has <Orange>It''s Jeff!</> ready, he can channel her power to conjure a ferocious <Orange>Jeff-nado</>! Additionally, a <Orange>Jeff-nado</> will form if Jeff encounters Storm''s <Orange>Omega Hurricane</> after devouring enemies with <Orange>It''s Jeff!</>. Enemies will be drawn into the swirling chaos after enduring sustained damage from the <Orange>Jeff-nado</> for some time.', 101582, '/abilities/101582.webp', 'Shark Surge', 'Passive', 3),
        (38, false, 'Fire Mystical Missiles to heal allies or deal damage to enemies.', 101621, '/abilities/101621.webp', 'Mystical Missile', 'Weapon', 4),
        (39, false, 'Use Rune Stones to create a magical field that provides allies <Buff>Healing Over Time</> and converts incoming damage into further healing.', 101631, '/abilities/101631.webp', 'Regeneration Domain', 'Normal', 4),
        (40, false, 'Become <Buff>Invisible</> and conjure an <Orange>Illusion</> to deceive enemies.', 101641, '/abilities/101641.webp', 'Deception', 'Normal', 4),
        (41, false, 'Project an <Orange>Illusion</> that can cast some of Loki''s abilities.', 101651, '/abilities/101651.webp', 'Doppelganger', 'Normal', 4),
        (42, false, 'Swap with the selected <Orange>Illusion</>.', 101652, '/abilities/101652.webp', 'Devious Exchange', 'Normal', 4),
        (43, false, 'Shapeshift into a targeted ally or enemy hero and use all their abilities except any of their Team-Up Abilities.', 101661, '/abilities/101661.webp', 'God Of Mischief', 'Ultimate', 4),
        (44, false, 'Pull out a dagger to stab enemies, dealing extra damage when attacking an enemy from behind.', 101611, '/abilities/101611.webp', 'Backstab', 'Normal', 4),
        (45, true, 'When Hela lands a final hit in defeating an enemy, she can instantly resurrect Thor in the respawn phase, or grant him <Buff>Bonus Health</> if he is still alive.', 101601, '/abilities/101601.webp', 'Laufeyson Reborn', 'Passive', 4),
        (46, true, 'Mantis enhances Groot''s wooden walls and Loki''s Rune Stones with life energy. Groot can additionally unleash a Wild Wall, which, when in <Orange>Flora Colossus</> state, restores health to random nearby allies. Loki''s Rune Stones grant allies within <Orange>Regeneration Domain</> a <Buff>Damage Boost</>.', 101632, '/abilities/101632.webp', 'Deific Blessing', 'Normal', 4),
        (47, false, 'Launch forward a cluster of splitting fireballs.', 101711, '/abilities/101711.webp', 'Fire Cluster', 'Weapon', 5),
        (48, false, 'HOLD {Ability2} to enter a state of <Buff>accelerated ascent</>.', 101721, '/abilities/101721.webp', 'Plasma Body', 'Normal', 5),
        (49, false, 'Launch a fireball to deal damage or create a <Orange>Flame Field</> at the targeted area, dealing damage to enemies within.', 101731, '/abilities/101731.webp', 'Blazing Blast', 'Normal', 5),
        (50, false, 'Dive towards the ground, dealing damage to enemies. This will also detonate any <Orange>Flame Fields</> hit and grant you <Buff>Bonus Health</>.', 101741, '/abilities/101741.webp', 'Flaming Meteor', 'Normal', 5),
        (51, false, 'When 2 or more  <Orange>Flame Fields</> exist, connect them to form a fire wall that deals one-off high damage to enemies that pass through the wall, or continuous burning damage if the wall exists in an enclosed area.', 101751, '/abilities/101751.webp', 'Pyro-prison', 'Normal', 5),
        (52, false, 'Explode with cosmic fire to deal damage to enemies within range and enter <Orange>Supernova</> state. While in Supernova state, <Orange>Blazing Blast</> will transform into <Orange>Flame Tornado</>, and <Orange>Plasma Body</> can be activated without any cost.', 101761, '/abilities/101761.webp', 'Supernova', 'Ultimate', 5),
        (53, true, 'When the Human Torch activates <Orange>Supernova</>, Storm can summon an <Orange>Omega Fire</> by selecting a <Orange>Flame Tornado</> with <Orange>Omega Hurricane</>. Likewise, when Storm unleashes <Orange>Omega Hurricane</>, the Human Torch can transform it into a <Orange>Burning Hurricane</> with <Orange>Supernova</>. Any <Orange>Flame Tornado</> caught in a <Orange>Burning Hurricane</> will grow in size and damage.', 101791, '/abilities/101791.webp', 'Omega Fire', 'Normal', 5),
        (54, true, 'The Invisible Woman taps into her powers, channeling Psionic Might to fortify the entire Fantastic Four team. This formidable force bolsters Human Torch, The Thing, and Mister Fantastic, granting damage resistance. Once activated, they can continually generate <Buff>Bonus Health</>, making up for lost Health.', 101792, '/abilities/101792.webp', 'United Siblings', 'Normal', 5),
        (55, true, 'Human Torch stores <Orange>Pyrokinetic Energy</> in Spider-Man''s suit, enabling him to unleash an <Orange>Inferno Blast</> that sprays a fiery web while performing a backflip to create distance. The flames damage enemies and apply a <Orange>Burn-Tracer</>. Detonating these <Orange>Burn-Tracers</> inflicts Damage Over Time.', 101793, '/abilities/101793.webp', 'Pyrokinetic Energy', 'Normal', 5),
        (56, true, 'Human Torch can lift The Thing into the air and slam him down, dealing damage, <Debuff>launching</> enemies, and creating a zone that disables mobility abilities.', 101794, '/abilities/101794.webp', 'Two In One', 'Normal', 5),
        (57, false, 'Separate nearby enemies'' <Orange>Souls</> from their bodies. Damage dealt to these <Orange>Souls</> is transferred to their physical bodies.', 101871, '/abilities/101871.webp', 'Eye Of Agamotto', 'Ultimate', 6),
        (58, false, 'Cast Daggers of Denak forward.', 101811, '/abilities/101811.webp', 'Daggers Of Denak', 'Weapon', 6),
        (59, false, 'Open portals between two locations, enabling all units to travel through them.', 101861, '/abilities/101861.webp', 'Pentagram Of Farallah', 'Normal', 6),
        (60, false, 'Create a protective barrier against damage.', 101841, '/abilities/101841.webp', 'Shield Of The Seraphim', 'Normal', 6),
        (61, false, 'Release <Orange>Dark Magic</> to deal damage to nearby enemies.', 101851, '/abilities/101851.webp', 'Maelstrom Of Madness', 'Normal', 6),
        (62, false, '<Orange>Dark Magic</> accumulates with every hit on an enemy. If <Orange>Dark Magic</> peaks for too long, Doctor Strange will be cursed with <Debuff>Anti-Heal</>.', 101881, '/abilities/101881.webp', 'Price Of Magic', 'Passive', 6),
        (63, false, 'Ascend and then enter a brief state of sustained flight.', 101891, '/abilities/101891.webp', 'Cloak Of Levitation', 'Normal', 6),
        (64, true, 'Hulk charges Namor with gamma radiation. When Namor receives the radiation, he will summon an extra <Orange>Gamma Monstro</> which, will continuously fire gamma rays at locked-on enemies. The longer the rays hit, the higher the damage.', 101852, '/abilities/101852.webp', 'Gamma Maelstrom', 'Normal', 6),
        (65, true, 'Doctor Strange shares his arcane mastery, replacing Scarlet Witch''s <Orange>Chthonian Burst</> with <Orange>Mystic Burst</> upon activation. Hold down the attack button to unleash a rapid, relentless salvo of magical missiles in the target direction.', 101892, '/abilities/101892.webp', 'Enchanted Enhancement', 'Normal', 6),
        (66, false, 'Release energy around her while moving, providing <Buff>Healing Over Time</> and <Buff>Movement Boosts</> for surrounding allies. Excess healing converts to <Buff>Bonus Health</>.', 102071, '/abilities/102071.webp', 'Soul Resurgence', 'Ultimate', 7),
        (67, false, 'Fire an energy thorn and regain one <Orange>Life Orb</> after a critical hit.', 102011, '/abilities/102011.webp', 'Life Energy Blast', 'Normal', 7),
        (68, false, 'Consume <Orange>Life Orbs</> to grant allies <Buff>Healing Over Time</>.', 102061, '/abilities/102061.webp', 'Healing Flower', 'Normal', 7),
        (69, false, 'Throw a spore to <Debuff>Sedate</> the nearest enemy.', 102051, '/abilities/102051.webp', 'Spore Slumber', 'Normal', 7),
        (70, false, 'Consume <Orange>Life Orbs</> to grant allies a <Buff>Damage Boost</>.', 102041, '/abilities/102041.webp', 'Allied Inspiration', 'Normal', 7),
        (71, false, 'Receive a <Buff>Movement Boost</> when not injured and <Orange>Healing Over Time</> when consuming <Buff>Life Orbs</>.', 102031, '/abilities/102031.webp', 'Nature''s Favor', 'Passive', 7),
        (72, false, 'Consume <Orange>Life Orbs</> to grant herself a <Buff>Damage Boost</>.', 102091, '/abilities/102091.webp', 'Natural Anger', 'Normal', 7),
        (73, true, 'Adam Warlock enhances the rebirth power of {104300}{000003}{102000}, granting them the power of cocooned revival.', 102081, '/abilities/102081.webp', 'Nature''s Soul', 'Normal', 7),
        (74, true, 'Mantis enhances Groot''s wooden walls and Loki''s Rune Stones with life energy. Groot can additionally unleash a Wild Wall, which, when in <Orange>Flora Colossus</> state, restores health to random nearby allies. Loki''s Rune Stones grant allies within <Orange>Regeneration Domain</> a <Buff>Damage Boost</>.', 102094, '/abilities/102094.webp', 'Heavenly Guardian', 'Passive', 7),
        (75, false, 'Perform a double jump in the direction of movement.', 102101, '/abilities/102101.webp', 'Skyward Leap', 'Normal', 8),
        (76, false, 'Aim at an enemy to improve focus, enhancing the damage inflicted by <Orange>Piercing Arrow</>.', 102111, '/abilities/102111.webp', 'Archer''s Focus', 'Passive', 8),
        (77, false, 'Shoot a powerful arrow.', 102131, '/abilities/102131.webp', 'Piercing Arrow', 'Weapon', 8),
        (78, false, 'Swing the wakizashi to strike frontal enemies, deflecting all incoming <Orange>projectiles</>.', 102191, '/abilities/102191.webp', 'Ronin Slash', 'Normal', 8),
        (79, false, 'Shoot three explosive arrows.', 102132, '/abilities/102132.webp', 'Blast Arrow', 'Weapon', 8),
        (80, false, 'Shoot a Hypersonic Arrow, dealing two instances of damage to enemies in its path and inflicting them with <Debuff>Slow</>. This ability can <Debuff>Knock Down</> flying heroes.', 102161, '/abilities/102161.webp', 'Hypersonic Arrow', 'Normal', 8),
        (81, false, 'Unsheathe a katana and slash forward, <Debuff>Launching Up</> hit enemies.', 102171, '/abilities/102171.webp', 'Crescent Slash', 'Normal', 8),
        (82, false, 'Capture <Orange>Afterimages</> of enemies in his view. Damage dealt to an <Orange>Afterimage</> is transferred to the corresponding enemy.', 102181, '/abilities/102181.webp', 'Hunter''s Sight', 'Ultimate', 8),
        (83, true, 'Hawkeye can share his Hunter''s Sight with Black Widow, enabling her to catch sight of and damage afterimages of enemies.', 102192, '/abilities/102192.webp', 'Supersensory Vision', 'Normal', 8),
        (84, true, 'Luna Snow grants Winter''s Chill to Hawkeye and Iron Fist. Hawkeye can shoot an <Orange>Ice Arrow</> that <Debuff>Stuns</> enemies if it travels a certain distance; otherwise, it <Debuff>Slows</> the target. The farther the arrow flies, the more damage it deals. When Iron Fist activates <Orange>Harmony Recovery</>, he can heal nearby allies with <Orange>Lunar Chi</>.', 102193, '/abilities/102193.webp', 'Ice Arrow', 'Normal', 8),
        (85, false, 'Get up close to strike enemies. Landing the second hit enables a shield throw that can ricochet four times.', 102235, '/abilities/102235.webp', 'Sentinel Strike', 'Weapon', 9),
        (86, false, 'Raise the shield to deflect incoming <Orange>Projectiles</>, sending them ricocheting in random directions.', 102241, '/abilities/102241.webp', 'Living Legend', 'Normal', 9),
        (87, false, 'Boost speed and enable <Orange>Fearless Leap</> to leap into the air.', 102251, '/abilities/102251.webp', 'Leading Dash', 'Normal', 9),
        (88, false, 'Slam down from the sky onto the targeted area, <Debuff>Launching Up</> enemies.', 102253, '/abilities/102253.webp', 'Super-soldier Slam', 'Normal', 9),
        (89, false, 'Hurl the energy-charged shield to strike enemies in a path.', 102261, '/abilities/102261.webp', 'Vibranium Energy Saw', 'Normal', 9),
        (90, false, 'Shield held high, carve a path forward, granting both himself and allies along the path continuous <Buff>Bonus Health</> and <Buff>Movement Boosts</>. Using <Orange>Living Legend</> and <Orange>Leading Dash</> while this ability is active can <Debuff>Launch Up</> enemies.', 102271, '/abilities/102271.webp', 'Freedom Charge', 'Ultimate', 9),
        (91, true, 'Thor infuses <Orange>Thorforce</> into {101500}{000003}{102200}, granting them an electrifying enhancement. {101501}{102201}', 102281, '/abilities/102281.webp', 'Charged Aegis', 'Normal', 9),
        (92, false, 'Raise the shield and charge forward.', 102236, '/abilities/102236.webp', 'Liberty Rush', 'Normal', 9),
        (93, true, 'Inspired by Captain America''s resolve, Winter Soldier can leap to the aid of a designated ally, slamming the ground with his mechanical arm to damage nearby foes and grant <Buff>Bonus Health</> to allies within range. Captain America and Winter Soldier can interact with each other once both parties confirm. The duo then collides and unleashes a shockwave that damages and <Debuff>slows</> enemies.', 102292, '/abilities/102292.webp', 'Captain''s Spirit', 'Normal', 9),
        (94, false, 'Hold {Jump} to run on a wall.', 102301, '/abilities/102301.webp', 'Wild Crawl', 'Passive', 10),
        (95, false, 'Fire energy projectiles that deal damage.', 102321, '/abilities/102321.webp', 'Bombard Mode', 'Weapon', 10),
        (96, false, 'Dash forward.', 102331, '/abilities/102331.webp', 'Jetpack Dash', 'Normal', 10),
        (97, false, 'Deploy a Battle Rebirth Beacon that revives a fallen ally and periodically produces <Orange>armor packs</> and <Orange>rocket jet packs</>.', 102341, '/abilities/102341.webp', 'B.r.b.', 'Normal', 10),
        (98, false, 'Deploy a Cosmic Yarn Amplifier that grants allies a <Buff>Damage Boost</>, while continuously providing them with <Buff>Bonus Health</>.', 102351, '/abilities/102351.webp', 'C.y.a.', 'Ultimate', 10),
        (99, false, 'Shoot bouncing spheres to heal allies. Directly hitting an ally provides extra healing.', 102322, '/abilities/102322.webp', 'Repair Mode', 'Weapon', 10),
        (100, false, 'Hold {Jump} to fall slowly.', 102332, '/abilities/102332.webp', 'Flying Ace', 'Passive', 10),
        (101, true, '{104700}{000003}{102300} can ride on Groot''s shoulders, receiving <Buff>Damage Reduction</>.', 102361, '/abilities/102361.webp', 'Old Friends', 'Normal', 10),
        (102, true, null, 102381, '/abilities/102381.webp', null, 'Normal', 10),
        (103, true, 'Rocket Raccoon throws an Ammo Overload Device in the target direction. Upon entering the device''s range, {101400} receive the buffs of <Buff>Infinite Ammo</> and <Buff>Faster Firing</>.', 102382, '/abilities/102382.webp', 'Ammo Invention', 'Normal', 10),
        (104, true, 'Rocket Raccoon upgrades his <Orange>B.R.B.</>, which now creates <Orange>Cyber-Webs</> upon placement and periodically spawns <Orange>Arachno-Mines</> and <Orange>Spider-Drones</>. Peni Parker can also deploy an <Orange>Armored Spider-Nest</> that drops <Orange>Armor Packs</> for <Buff>Bonus Health</>. Star-Lord gets a teleport to its deployment point from anywhere on the map.', 102392, '/abilities/102392.webp', 'Rocket Network', 'Normal', 10),
        (105, false, 'Throw Nightsword Thorns.', 102431, '/abilities/102431.webp', 'Nightsword Thorn', 'Weapon', 11),
        (106, false, 'Defeating an enemy will generate a Nastrond Crow, exploding after a duration.', 102411, '/abilities/102411.webp', 'Nastrond Crowstorm', 'Passive', 11),
        (107, false, 'Fire multiple Nightsword Thorns that detonate after a delay.', 102441, '/abilities/102441.webp', 'Piercing Night', 'Normal', 11),
        (108, false, 'Transform into a Nastrond Crow to glide forth, press again to undo the transformation.', 102451, '/abilities/102451.webp', 'Astral Flock', 'Normal', 11),
