        (235, false, 'Shoot webbing to reel in the hit enemy. If the enemy is tagged with a <Orange>Spider-Tracer</>, Spider-Man will get pulled to them instead.', 103631, '/abilities/103631.webp', 'Get Over Here!', 'Normal', 23),
