        (258, false, 'Engage in free-flight while charging energy, then unleash it to deal massive damage.', 103851, '/abilities/103851.webp', 'Reality Erasure', 'Normal', 25),
        (259, true, 'Scarlet Witch can infuse Chaos Energy into Magneto to enchant his greatsword. Upon receiving the Chaos Energy, Magneto can unleash its full force, striking down enemies with his enchanted greatsword.', 103881, '/abilities/103881.webp', 'Chaotic Bond', 'Normal', 25),
        (260, true, 'Doctor Strange shares his arcane mastery, replacing Scarlet Witch''s <Orange>Chthonian Burst</> with <Orange>Mystic Burst</> upon activation. Hold down the attack button to unleash a rapid, relentless salvo of magical missiles in the target direction.', 103891, '/abilities/103891.webp', 'Sorcery Surge', 'Normal', 25),
        (261, false, 'Consume <Orange>Thorforce</> to gain <Buff>Bonus Health</>. Landing <Orange>Mjölnir Bash</> on an enemy instantly recharges <Orange>Thorforce</>.', 103901, '/abilities/103901.webp', 'Thorforce', 'Passive', 26),
        (262, false, 'Wield Mjölnir to strike enemies. When <Orange>Awakened</>, Thor can launch lightning arc waves to deal damage.', 103911, '/abilities/103911.webp', 'Mjölnir Bash', 'Normal', 26),
        (263, false, 'Throw Mjolnir forward which then returns. Restore <Orange>Thorforce</> upon hit.', 103921, '/abilities/103921.webp', 'Hammer Throw', 'Normal', 26),
        (264, false, 'Summon lightning to restore <Orange>Thorforce</> based on the number of hit enemies. Enemies leaving the Lightning Realm will suffer <Debuff>Slow</> and <Debuff>Grounded</> effects.', 103931, '/abilities/103931.webp', 'Lightning Realm', 'Normal', 26),
