        (266, false, 'Consume <Orange>Thorforce</> to enter the <Orange>Awakened</> state, granting <Buff>Bonus Health</> and enhancing Mjölnir Bash. Gain <Orange>Thorforce</> upon exiting the state.', 103951, '/abilities/103951.webp', 'Awakening Rune', 'Normal', 26),
        (267, false, 'Soar upwards and smite the ground after charging for a duration, inflicting damage on enemies within range.', 103961, '/abilities/103961.webp', 'God Of Thunder', 'Ultimate', 26),
        (268, true, 'When Hela lands a final hit in defeating an enemy, she can instantly resurrect Thor in the respawn phase, or grant him <Buff>Bonus Health</> if he is still alive.', 103902, '/abilities/103902.webp', 'Odinson Reborn', 'Passive', 26),
        (269, true, 'Thor infuses <Orange>Thorforce</> into {101500}{000003}{102200}, granting them an electrifying enhancement. {101501}{102201}', 103981, '/abilities/103981.webp', 'Thunderous Deity', 'Passive', 26),
        (270, false, 'Using abilities generates <Orange>Elasticity</>. Reaching full <Orange>Elasticity</> triggers an Inflated state that grants <Buff>Shield</> and enhanced damage.', 104001, '/abilities/104001.webp', 'Elastic Strength', 'Passive', 27),
        (271, false, 'Stretch out a forward punch to attack enemies.', 104011, '/abilities/104011.webp', 'Stretch Punch', 'Weapon', 27),
        (272, false, 'Extend arms forward to entangle an enemy, then press {PrimaryAttack} to pull the hit enemy toward you, or select and yank another enemy, <Debuff>knocking them airborne</> against each other.', 104031, '/abilities/104031.webp', 'Distended Grip', 'Normal', 27),
        (273, false, 'Gain a <Buff>Shield</>, select a target, and dash towards them, dealing damage to enemies and granting a <Buff>Shield</> to allies.', 104041, '/abilities/104041.webp', 'Flexible Elongation', 'Normal', 27),
