        (302, false, 'Consume energy to gain a <Buff>Movement Boost</> and soar forward.', 104392, '/abilities/104392.webp', 'ROCKET PROPULSION', 'Normal', 30),
        (303, false, 'Fire bullets in all directions, launching up nearby enemies and causing them to lose the ball. This ability can only be used when not in possession of the ball.', 104393, '/abilities/104393.webp', 'LION LEAP', 'Normal', 30),
        (304, false, 'Dodge in the direction of movement and swiftly reload. Become <Buff>Unstoppable</> and <Buff>Invincible</> while dodging.', 104381, '/abilities/104381.webp', 'CELESTIAL LEAP', 'Normal', 30),
        (305, true, 'Rocket Raccoon upgrades his <Orange>B.R.B.</>, which now creates <Orange>Cyber-Webs</> upon placement and periodically spawns <Orange>Arachno-Mines</> and <Orange>Spider-Drones</>. Peni Parker can also deploy an <Orange>Armored Spider-Nest</> that drops <Orange>Armor Packs</> for <Buff>Bonus Health</>. Star-Lord gets a teleport to its deployment point from anywhere on the map.', 104395, '/abilities/104395.webp', 'Network Leapspider', 'Normal', 30),
        (306, false, 'Throw the trident forward, reducing <Orange>Aquatic Dominion''s</> cooldown upon enemy impact. Critical hits cause <Orange>Monstro Spawn</> to enter a berserk state, gaining increased Attack Speed.', 104521, '/abilities/104521.webp', 'Trident Of Neptune', 'Normal', 31),
        (307, false, 'Launch the trident forward to damage nearby enemies, then direct all <Orange>Monstro Spawn</> to perform an enhanced attack on the nearest hit enemy. When the trident hits an enemy, <Orange>Monstro Spawn</> to enter a berserk state, gaining increased Attack Speed.', 104531, '/abilities/104531.webp', 'Wrath Of The Seven Seas', 'Normal', 31),
