        (323, false, 'Launch a high-speed water sphere that bursts upon impact, dealing damage to enemies within range. Direct hits <Debuff>Launch Up</> enemies.', 104721, '/abilities/104721.webp', 'Aqua Burst', 'Normal', 33),
        (324, false, 'Spit a bubble that heals the ally who collects it, granting them <Buff>Healing</> and <Buff>Movement Boost</>.', 104751, '/abilities/104751.webp', 'Healing Bubble', 'Normal', 33),
