        (330, false, 'Unleash a damaging splash. This ability can paint the ground.', 104713, '/abilities/104713.webp', 'Snow Splash', 'Weapon', 33),
        (331, false, 'Launch a high-speed snowball that bursts upon impact, dealing damage to enemies within range. This ability can paint the ground.', 104723, '/abilities/104723.webp', 'Frost Burst', 'Weapon', 33),
        (332, false, 'Spit a bubble that explodes after a short delay, dealing damage; using this Ability can paint the ground.', 104752, '/abilities/104752.webp', 'Blasting Bubble', 'Normal', 33),
        (333, false, 'Dive into the scene with only his dorsal fin exposed, granting himself a <Buff>Movement Boost</>. Jeff can heal while submerged and gains the wall-crawl ability.', 104764, '/abilities/104764.webp', 'Hide And Seek', 'Normal', 33),
        (334, false, 'Deep dive into the scene and resurface to swallow both enemies and allies within range, activating <Orange>Hide and Seek</> for a brief duration before ejecting the swallowed heroes forward. Use this ability to paint the ground.', 104772, '/abilities/104772.webp', 'It''s Jeff!', 'Ultimate', 33),
        (335, true, 'When Storm unleashes her <Orange>Omega Hurricane</>, if Jeff the Land Shark has <Orange>It''s Jeff!</> ready, he can channel her power to conjure a ferocious <Orange>Jeff-nado</>! Additionally, a <Orange>Jeff-nado</> will form if Jeff encounters Storm''s <Orange>Omega Hurricane</> after devouring enemies with <Orange>It''s Jeff!</>. Enemies will be drawn into the swirling chaos after enduring sustained damage from the <Orange>Jeff-nado</> for some time.', 104784, '/abilities/104784.webp', 'It''s Jeff-nado!', 'Normal', 33),
        (336, true, 'Venom shares his symbiotes with Jeff and Hela. Jeff''s <Orange>Guardian of the Deep</> links with nearby allies for continuous healing, releasing a large healing burst that converts any excess into <Buff>Bonus Health</> when it ends. Hela''s <Orange>Hel Tendrils</> unleash a symbiotic Hel Sphere that pulls in nearby enemies and links them, <Debuff>slowing</> those that try to escape.', 104783, '/abilities/104783.webp', 'Guardian Of The Deep', 'Normal', 33),
        (337, false, 'Unleash bolts with psionic crossbows to damage enemies and reduce the cooldowns of all her abilities.', 104821, '/abilities/104821.webp', 'Psionic Crossbow', 'Normal', 34),
        (338, false, 'Launch a volley of psionic shurikens that stick to enemies, dealing damage and granting herself <Buff>Bonus Health</>. Press again to recall the shurikens.', 104831, '/abilities/104831.webp', 'Wing Shurikens', 'Normal', 34),
        (339, false, 'Dash forward and slice through enemies along the path with psionic blades.', 104841, '/abilities/104841.webp', 'Psi-blade Dash', 'Normal', 34),
